        ClassItem(id: 'det1', name: Bi('Bank reconciliation', 'تسوية البنك'), category: 'detective', hint: Bi('Detects discrepancies after transactions', 'يكتشف التناقضات بعد المعاملات')),
        ClassItem(id: 'det2', name: Bi('Budget variance analysis', 'تحليل انحراف الميزانية'), category: 'detective', hint: Bi('Identifies spending deviations', 'يحدد انحرافات الإنفاق')),
