        ClassItem(id: 'det4', name: Bi('Internal audit reviews', 'مراجعات التدقيق الداخلي'), category: 'detective', hint: Bi('Finds control weaknesses', 'يجد نقاط ضعف الرقابة')),
        ClassItem(id: 'det5', name: Bi('Exception reports', 'تقارير الاستثناءات'), category: 'detective', hint: Bi('Highlights unusual transactions', 'يسلط الضوء على المعاملات غير العادية')),
        ClassItem(id: 'det6', name: Bi('Data analytics and pattern detection', 'تحليلات البيانات واكتشاف الأنماط'), category: 'detective', hint: Bi('Identifies anomalies in data', 'يحدد الشذوذات في البيانات')),
        ClassItem(id: 'det7', name: Bi('Surprise audits', 'عمليات التدقيق المفاجئة'), category: 'detective', hint: Bi('Uncovers hidden issues', 'يكشف المشاكل المخفية')),
        ClassItem(id: 'det8', name: Bi('Transaction monitoring systems', 'أنظمة مراقبة المعاملات'), category: 'detective', hint: Bi('Tracks transactions for irregularities', 'يتتبع المعاملات للكشف عن المخالفات')),
        ClassItem(id: 'det9', name: Bi('Account reconciliation reviews', 'مراجعات تسوية الحسابات'), category: 'detective', hint: Bi('Verifies account accuracy', 'يتحقق من دقة الحساب')),
        ClassItem(id: 'corr1', name: Bi('Disciplinary action for violations', 'إجراء تأديبي للمخالفات'), category: 'corrective', hint: Bi('Fixes behavior issues', 'يصلح مشاكل السلوك')),
        ClassItem(id: 'corr2', name: Bi('Process redesign after failures', 'إعادة تصميم العملية بعد الفشل'), category: 'corrective', hint: Bi('Improves weak processes', 'يحسن العمليات الضعيفة')),
        ClassItem(id: 'corr3', name: Bi('System patches and updates', 'تصحيحات وتحديثات النظام'), category: 'corrective', hint: Bi('Fixes security vulnerabilities', 'يصلح نقاط الضعف الأمنية')),
        ClassItem(id: 'corr4', name: Bi('Disaster recovery plans', 'خطط التعافي من الكوارث'), category: 'corrective', hint: Bi('Restores operations after incidents', 'يستعيد العمليات بعد الحوادث')),
        ClassItem(id: 'corr5', name: Bi('Fraud remediation programs', 'برامج معالجة الاحتيال'), category: 'corrective', hint: Bi('Addresses fraud after discovery', 'يعالج الاحتيال بعد اكتشافه')),
        ClassItem(id: 'corr6', name: Bi('Policy updates after incidents', 'تحديثات السياسة بعد الحوادث'), category: 'corrective', hint: Bi('Prevents recurrence through policy changes', 'يمنع التكرار من خلال تغييرات السياسة')),
        ClassItem(id: 'corr7', name: Bi('Corrective action plans', 'خطط الإجراءات التصحيحية'), category: 'corrective', hint: Bi('Remedies identified deficiencies', 'يعالج أوجه القصور المحددة')),
