    ModuleActivity(
      id: 'complianceOrdering',
      tab: ActivityTab.games,
      kind: ActivityKind.ordering,
      title: Bi('Compliance Process Sequencer', 'مرتب عمليات الامتثال'),
      description: Bi('Arrange the five compliance process steps in order', 'رتب خطوات عملية الامتثال الخمس بالترتيب الصحيح'),
      maxScore: 25,
      instruction: Bi('Arrange the five compliance framework lifecycle steps in the correct order from start to finish', 'رتب خطوات دورة حياة إطار الامتثال الخمس بالترتيب الصحيح من البداية إلى النهاية'),
      steps: [
        OrderStep(id: 'step1', name: Bi('Identify Regulatory Requirements', 'تحديد المتطلبات التنظيمية'), description: Bi('Map all applicable laws, regulations, standards, and internal policies that apply to the organization', 'رسم خريطة لجميع القوانين واللوائح والمعايير والسياسات الداخلية المطبقة على المنظمة'), hint: Bi('This is the foundation - you must know what rules apply before anything else', 'هذا هو الأساس - يجب أن تعرف ما القواعد المطبقة قبل أي شيء آخر')),
        OrderStep(id: 'step2', name: Bi('Assess Compliance Risks', 'تقييم مخاطر الامتثال'), description: Bi('Evaluate the likelihood and impact of non-compliance, identify gaps between current state and requirements', 'تقييم احتمال وتأثير عدم الامتثال، تحديد الفجوات بين الحالة الحالية والمتطلبات'), hint: Bi('After knowing the rules, assess where your organization might fall short', 'بعد معرفة القواعد، قيم أين قد تقصر منظمتك')),
        OrderStep(id: 'step3', name: Bi('Design & Implement Controls', 'تصميم وتنفيذ الضوابط'), description: Bi('Create and implement preventive, detective, and corrective controls to mitigate identified risks', 'إنشاء وتنفيذ ضوابط وقائية واستكشافية وتصحيحية لتخفيف المخاطر المحددة'), hint: Bi('Build control mechanisms to address the risks you identified', 'بناء آليات رقابة لمعالجة المخاطر التي حددتها')),
        OrderStep(id: 'step4', name: Bi('Monitor & Test Effectiveness', 'مراقبة واختبار الفعالية'), description: Bi('Continuously monitor controls, conduct testing, perform internal audits, and track compliance metrics', 'المراقبة المستمرة للضوابط، إجراء الاختبارات، تنفيذ التدقيق الداخلي، وتتبع مقاييس الامتثال'), hint: Bi('Verify that the controls you implemented are actually working as designed', 'تحقق من أن الضوابط التي نفذتها تعمل فعلاً كما صممت')),
        OrderStep(id: 'step5', name: Bi('Report & Remediate', 'الإبلاغ والمعالجة'), description: Bi('Report compliance status to stakeholders, address any deficiencies found, and implement corrective actions', 'الإبلاغ عن حالة الامتثال لأصحاب المصلحة، معالجة أي أوجه قصور موجودة، وتنفيذ إجراءات تصحيحية'), hint: Bi('The final step: communicate results to leadership and fix any problems discovered', 'الخطوة الأخيرة: إبلاغ النتائج للقيادة وإصلاح أي مشاكل مكتشفة')),
      ],
    ),
    ModuleActivity(
      id: 'internalControlsSimulator',
      tab: ActivityTab.sim,
      kind: ActivityKind.caseScenario,
      title: Bi('Internal Controls Simulator', 'محاكاة الضوابط الداخلية'),
      description: Bi('Apply compliance and internal control principles', 'طبق مبادئ الامتثال والضوابط الداخلية'),
      maxScore: 100,
      instruction: Bi('Apply compliance and internal control principles to real-world business scenarios. Evaluate control environments, identify weaknesses, and recommend corrective actions.', 'طبق مبادئ الامتثال والضوابط الداخلية على سيناريوهات أعمال واقعية. قيم بيئات الرقابة، وحدد مواطن الضعف، وأوص بإجراءات تصحيحية.'),
      scenarios: [
        CaseScenario(id: 'segregation-of-duties', title: Bi('Segregation of Duties Weakness', 'ضعف في الفصل بين المهام'), role: Bi('Internal Audit Director', 'مدير التدقيق الداخلي'), overview: Bi('You are the new Internal Audit Director at a Saudi company. During a routine review, you discover that Ahmed Al-Mutairi, a senior finance officer, has been approving purchase requisitions and also processing the corresponding payments for the past 18 months. This violates the fundamental principle of segregation of duties and creates significant fraud risk.', 'أنت مدير التدقيق الداخلي الجديد في شركة سعودية. أثناء مراجعة روتينية، تكتشف أن Ahmed Al-Mutairi، وهو مسؤول مالي أول، ظل يعتمد طلبات الشراء ويعالج أيضا المدفوعات المقابلة لها على مدى الأشهر الـ 18 الماضية. وهذا ينتهك المبدأ الأساسي للفصل بين المهام ويخلق مخاطر احتيال كبيرة.'), finalSummary: Bi('You successfully identified a critical segregation of duties weakness, investigated for fraud, designed proper preventive controls with system enforcement, and established ongoing monitoring. This case demonstrates how internal control frameworks (COSO) must be embedded in systems and processes, not just documented in policies. Strong controls require: (1) Preventive controls that stop issues, (2) Detective controls that identify problems, and (3) Corrective controls that fix root causes. Your work has significantly reduced fraud risk at the company.', 'نجحت في تحديد ضعف حرج في الفصل بين المهام، وحققت في الاحتيال، وصممت ضوابط وقائية سليمة مدعومة بالفرض النظامي، وأنشأت مراقبة مستمرة. وتوضح هذه الحالة كيف يجب أن تكون أطر الضوابط الداخلية (COSO) مدمجة في الأنظمة والعمليات، لا موثقة في السياسات فحسب. وتتطلب الضوابط القوية: (1) ضوابط وقائية توقف المشكلات، (2) ضوابط كاشفة تحدد المشكلات، (3) ضوابط تصحيحية تعالج الأسباب الجذرية. وقد قلل عملك بشكل كبير من مخاطر الاحتيال في الشركة.'), steps: [
            CaseStep(id: 'step1', type: CaseStepType.analysis, title: Bi('Initial Risk Assessment', 'التقييم الأولي للمخاطر'), description: Bi('You review the transaction logs and discover that Ahmed has processed over 450 transactions totaling SAR 8.2 million. The current system allows him to both create purchase orders and authorize payments without secondary approval.', 'تراجع سجلات المعاملات وتكتشف أن Ahmed عالج أكثر من 450 معاملة بإجمالي 8.2 مليون SAR. ويسمح له النظام الحالي بإنشاء أوامر الشراء واعتماد المدفوعات معا دون اعتماد ثانوي.'), data: [CaseDatum(Bi('Transactions Processed', 'المعاملات المعالجة'), '450'), CaseDatum(Bi('Total Value', 'القيمة الإجمالية'), 'SAR 8.2M'), CaseDatum(Bi('Time Period', 'الفترة الزمنية'), '18 months'), CaseDatum(Bi('Secondary Approvals', 'الاعتمادات الثانوية'), '0')], question: Bi('Which COSO Internal Control component is primarily compromised in this situation?', 'أي مكون من مكونات الضوابط الداخلية في إطار COSO هو المتأثر بشكل أساسي في هذا الموقف؟'), options: [
                CaseOption(Bi('Control Environment - The tone at the top is weak', 'بيئة الرقابة - توجه القيادة العليا ضعيف'), feedback: Bi('While tone at the top is important, the primary issue here is the lack of proper control activities, specifically segregation of duties. Control environment refers to organizational culture and ethical values.', 'رغم أهمية توجه القيادة العليا، فإن المشكلة الأساسية هنا هي غياب أنشطة الرقابة السليمة، وتحديدا الفصل بين المهام. تشير بيئة الرقابة إلى الثقافة المؤسسية والقيم الأخلاقية.')),
                CaseOption(Bi('Control Activities - Segregation of duties is absent', 'أنشطة الرقابة - غياب الفصل بين المهام'), isCorrect: true, feedback: Bi('Correct! This is a clear failure of control activities. Segregation of duties requires that no single individual should have control over all phases of a transaction. Approval and payment should be separated to prevent fraud and errors.', 'صحيح! هذا فشل واضح في أنشطة الرقابة. يتطلب الفصل بين المهام ألا يتحكم أي فرد بمفرده في جميع مراحل المعاملة. ويجب الفصل بين الاعتماد والدفع لمنع الاحتيال والأخطاء.')),
                CaseOption(Bi('Monitoring - Ongoing supervision is lacking', 'المراقبة - الإشراف المستمر غير متوفر'), feedback: Bi('While monitoring could have detected this issue earlier, the root problem is the absence of proper segregation of duties in the control activities. Monitoring is a secondary concern here.', 'رغم أن المراقبة كان يمكن أن تكشف هذه المشكلة في وقت أبكر، فإن المشكلة الجذرية هي غياب الفصل السليم بين المهام ضمن أنشطة الرقابة. وتعد المراقبة هنا مسألة ثانوية.')),
                CaseOption(Bi('Information & Communication - Poor reporting systems', 'المعلومات والاتصال - ضعف أنظمة إعداد التقارير'), feedback: Bi('Information systems are not the primary issue. The fundamental problem is that the control structure allows one person to both authorize and execute transactions.', 'أنظمة المعلومات ليست المشكلة الأساسية. فالمشكلة الجوهرية هي أن هيكل الرقابة يسمح لشخص واحد باعتماد المعاملات وتنفيذها معا.')),
            ]),
            CaseStep(id: 'step2', type: CaseStepType.analysis, title: Bi('Evidence Gathering', 'جمع الأدلة'), description: Bi('You need to determine if any fraudulent activity has occurred. Your audit team begins detailed transaction testing of Ahmed\'s payments.', 'يتعين عليك تحديد ما إذا كان قد وقع أي نشاط احتيالي. يبدأ فريق التدقيق لديك في اختبار تفصيلي للمعاملات المتعلقة بمدفوعات Ahmed.'), context: Bi('Detective controls help identify issues after they occur. For payment fraud, you should look for red flags such as duplicate invoices, payments to related parties, unusual patterns, or transactions just below approval thresholds.', 'تساعد الضوابط الكاشفة في تحديد المشكلات بعد وقوعها. وفي احتيال المدفوعات، ينبغي البحث عن مؤشرات تحذيرية مثل الفواتير المكررة، والمدفوعات للأطراف ذات العلاقة، والأنماط غير المعتادة، أو المعاملات التي تقل قليلا عن حدود الاعتماد.'), question: Bi('Which testing approach would be MOST effective in detecting potential fraud?', 'أي منهج اختبار سيكون الأكثر فعالية في كشف الاحتيال المحتمل؟'), options: [
                CaseOption(Bi('Random sampling - Test 30 transactions randomly selected', 'العينة العشوائية - اختبار 30 معاملة يتم اختيارها عشوائيا'), feedback: Bi('Random sampling may miss targeted fraud. A risk-based approach focusing on high-risk indicators would be more effective for fraud detection.', 'قد تغفل العينة العشوائية عن الاحتيال المستهدف. والمنهج القائم على المخاطر الذي يركز على المؤشرات عالية الخطورة سيكون أكثر فعالية في كشف الاحتيال.')),
                CaseOption(Bi('Data analytics - Screen all 450 transactions for red flags (duplicates, split transactions, vendor patterns)', 'تحليلات البيانات - فحص جميع المعاملات الـ 450 بحثا عن المؤشرات التحذيرية (التكرارات، والمعاملات المجزأة، وأنماط الموردين)'), isCorrect: true, feedback: Bi('Excellent choice! Data analytics allows you to screen the entire population for fraud indicators such as duplicate payments, artificially split transactions below approval thresholds, payments to shell companies, or unusual vendor relationships. This is far more effective than sampling.', 'اختيار ممتاز! تتيح لك تحليلات البيانات فحص المجتمع الإحصائي بأكمله بحثا عن مؤشرات الاحتيال مثل المدفوعات المكررة، والمعاملات المجزأة بشكل مصطنع لتبقى دون حدود الاعتماد، والمدفوعات لشركات وهمية، أو العلاقات غير المعتادة مع الموردين. وهذا أكثر فعالية بكثير من أخذ العينات.'), consequence: Bi('Your analysis reveals 12 suspicious transactions totaling SAR 340,000, including 3 duplicate payments and 9 payments to a vendor registered to Ahmed\'s brother-in-law.', 'يكشف تحليلك عن 12 معاملة مشبوهة بإجمالي 340,000 SAR، من بينها 3 مدفوعات مكررة و 9 مدفوعات لمورد مسجل باسم صهر Ahmed.')),
                CaseOption(Bi('External confirmation - Contact all vendors to verify invoices', 'المصادقة الخارجية - التواصل مع جميع الموردين للتحقق من الفواتير'), feedback: Bi('While vendor confirmations are useful, they are time-consuming for 450 transactions and may not reveal internal control issues or collusion. Data analytics would be more efficient as a first step.', 'رغم فائدة مصادقات الموردين، فإنها تستغرق وقتا طويلا مع 450 معاملة وقد لا تكشف عن مشكلات الضوابط الداخلية أو التواطؤ. وتكون تحليلات البيانات أكثر كفاءة كخطوة أولى.')),
                CaseOption(Bi('Interview Ahmed\'s manager to understand the process', 'مقابلة مدير Ahmed لفهم العملية'), feedback: Bi('Interviews provide context but won\'t reveal whether fraud occurred. You need transaction-level evidence first, then interviews can follow to understand how controls failed.', 'توفر المقابلات سياقا لكنها لن تكشف ما إذا كان الاحتيال قد وقع. فأنت بحاجة أولا إلى أدلة على مستوى المعاملات، ثم يمكن أن تليها المقابلات لفهم كيفية فشل الضوابط.')),
            ]),
            CaseStep(id: 'step3', type: CaseStepType.recommendation, title: Bi('Control Design', 'تصميم الضوابط'), description: Bi('Your investigation has identified control weaknesses and suspicious transactions. Now you must recommend a control structure to prevent future violations. The company wants a practical solution that balances control strength with operational efficiency.', 'حدد تحقيقك مواطن ضعف في الضوابط ومعاملات مشبوهة. والآن عليك التوصية بهيكل رقابي لمنع المخالفات المستقبلية. وترغب الشركة في حل عملي يوازن بين قوة الرقابة والكفاءة التشغيلية.'), data: [CaseDatum(Bi('Monthly Transactions', 'المعاملات الشهرية'), '~25'), CaseDatum(Bi('Finance Staff', 'موظفو المالية'), '8 people'), CaseDatum(Bi('Average Transaction', 'متوسط المعاملة'), 'SAR 18,000')], question: Bi('What is the MOST appropriate segregation of duties control for the payment process?', 'ما هو ضابط الفصل بين المهام الأنسب لعملية الدفع؟'), options: [
                CaseOption(Bi('Three-way segregation: Separate people for (1) requisition, (2) approval, (3) payment processing', 'الفصل الثلاثي: أشخاص منفصلون لكل من (1) طلب الشراء، (2) الاعتماد، (3) معالجة الدفع'), isCorrect: true, feedback: Bi('Perfect! This is the gold standard for payment controls. The requisitioner initiates, a manager approves, and a separate payment processor executes. No single person controls the entire cycle. This is a fundamental preventive control.', 'ممتاز! هذا هو المعيار الذهبي لضوابط الدفع. فطالب الشراء يبدأ العملية، ومدير يعتمدها، ومعالج دفع منفصل ينفذها. ولا يتحكم أي شخص بمفرده في الدورة بأكملها. وهذا ضابط وقائي أساسي.'), consequence: Bi('The company implements three-way segregation with system controls that prevent users from performing conflicting roles. Ahmed is reassigned to budget analysis.', 'تطبق الشركة الفصل الثلاثي مع ضوابط نظامية تمنع المستخدمين من أداء أدوار متعارضة. ويعاد تكليف Ahmed بمهام تحليل الموازنة.')),
                CaseOption(Bi('Dual approval: Require two signatures on all payments', 'الاعتماد المزدوج: اشتراط توقيعين على جميع المدفوعات'), feedback: Bi('While dual approval adds a layer of review, it doesn\'t address segregation of duties if the same person who requested the payment is one of the approvers. You need separation between requisition, approval, and execution.', 'رغم أن الاعتماد المزدوج يضيف طبقة من المراجعة، فإنه لا يعالج الفصل بين المهام إذا كان الشخص نفسه الذي طلب الدفع أحد المعتمدين. فأنت بحاجة إلى الفصل بين طلب الشراء والاعتماد والتنفيذ.')),
                CaseOption(Bi('Approval thresholds: Require director approval for payments over SAR 50,000', 'حدود الاعتماد: اشتراط اعتماد المدير للمدفوعات التي تتجاوز 50,000 SAR'), feedback: Bi('Thresholds are helpful but incomplete. They don\'t prevent someone from splitting large transactions or creating fictitious small payments. Segregation of duties should apply to all transactions.', 'الحدود مفيدة لكنها غير مكتملة. فهي لا تمنع شخصا من تجزئة المعاملات الكبيرة أو إنشاء مدفوعات صغيرة وهمية. وينبغي أن ينطبق الفصل بين المهام على جميع المعاملات.')),
                CaseOption(Bi('Quarterly review: Internal audit reviews all payments every quarter', 'المراجعة الفصلية: يراجع التدقيق الداخلي جميع المدفوعات كل ربع سنة'), feedback: Bi('Quarterly reviews are detective controls that identify issues after they occur. You need preventive controls (segregation of duties) to stop fraud from happening in the first place.', 'المراجعات الفصلية هي ضوابط كاشفة تحدد المشكلات بعد وقوعها. وأنت بحاجة إلى ضوابط وقائية (الفصل بين المهام) لمنع الاحتيال من الحدوث أساسا.')),
            ]),
            CaseStep(id: 'step4', type: CaseStepType.decision, title: Bi('System Implementation', 'تنفيذ النظام'), description: Bi('The company has approved your three-way segregation recommendation. Now you must configure the financial system to enforce these controls. The IT department can implement role-based access controls.', 'اعتمدت الشركة توصيتك بالفصل الثلاثي. والآن عليك تهيئة النظام المالي لفرض هذه الضوابط. ويمكن لقسم تقنية المعلومات تطبيق ضوابط الوصول القائمة على الأدوار.'), question: Bi('Which system configuration will BEST enforce segregation of duties?', 'أي تهيئة للنظام ستفرض الفصل بين المهام على أفضل وجه؟'), options: [
                CaseOption(Bi('Create mutually exclusive user roles: Users assigned to "Approval" role cannot be assigned to "Payment" role', 'إنشاء أدوار مستخدمين متنافية: لا يمكن للمستخدمين المعينين على دور الاعتماد أن يعينوا على دور الدفع'), isCorrect: true, feedback: Bi('Excellent! Mutually exclusive roles (also called incompatible functions) are the strongest preventive control. The system physically prevents users from having conflicting permissions. This is a compensating control when you can\'t separate duties through different people.', 'ممتاز! الأدوار المتنافية (وتسمى أيضا الوظائف غير المتوافقة) هي أقوى ضابط وقائي. فالنظام يمنع فعليا المستخدمين من امتلاك صلاحيات متعارضة. وهذا ضابط تعويضي عندما يتعذر الفصل بين المهام عبر أشخاص مختلفين.'), consequence: Bi('The system now blocks any attempt to assign conflicting roles to the same user. An automated conflict check runs weekly and alerts management to any violations.', 'أصبح النظام الآن يمنع أي محاولة لتعيين أدوار متعارضة للمستخدم نفسه. ويعمل فحص آلي للتعارضات أسبوعيا وينبه الإدارة إلى أي مخالفات.')),
                CaseOption(Bi('Display a warning message when users try to approve their own payments', 'عرض رسالة تحذيرية عندما يحاول المستخدمون اعتماد مدفوعاتهم الخاصة'), feedback: Bi('Warning messages are weak controls because they can be ignored. You need the system to prevent the action, not just warn about it. This is called a hard control vs. a soft control.', 'الرسائل التحذيرية ضوابط ضعيفة لأنه يمكن تجاهلها. فأنت بحاجة إلى أن يمنع النظام الإجراء، لا أن يحذر منه فحسب. وهذا ما يسمى بالضابط الصارم مقابل الضابط المرن.')),
                CaseOption(Bi('Allow the process but log all instances where someone approves their own payment for audit review', 'السماح بالعملية مع تسجيل جميع الحالات التي يعتمد فيها شخص مدفوعاته الخاصة لمراجعتها من قبل التدقيق'), feedback: Bi('Logging is a detective control that identifies issues after they occur. You need preventive controls that stop violations from happening. Logging should supplement prevention, not replace it.', 'التسجيل ضابط كاشف يحدد المشكلات بعد وقوعها. وأنت بحاجة إلى ضوابط وقائية تمنع حدوث المخالفات. وينبغي أن يكمل التسجيل الوقاية لا أن يحل محلها.')),
                CaseOption(Bi('Restrict the ability but allow managers to override with a special code', 'تقييد الصلاحية مع السماح للمديرين بتجاوزها برمز خاص'), feedback: Bi('Manual overrides undermine segregation of duties and create a backdoor for fraud. Overrides should be extremely rare and require documented business justification with independent approval.', 'التجاوزات اليدوية تقوض الفصل بين المهام وتخلق بابا خلفيا للاحتيال. وينبغي أن تكون التجاوزات نادرة للغاية وأن تتطلب مبررا تجاريا موثقا مع اعتماد مستقل.')),
            ]),
            CaseStep(id: 'step5', type: CaseStepType.recommendation, title: Bi('Ongoing Monitoring', 'المراقبة المستمرة'), description: Bi('The new controls have been in place for 6 months. You need to establish an ongoing monitoring program to ensure controls remain effective and identify any emerging issues.', 'مضت 6 أشهر على تطبيق الضوابط الجديدة. وتحتاج إلى إنشاء برنامج مراقبة مستمرة لضمان بقاء الضوابط فعالة وتحديد أي مشكلات ناشئة.'), context: Bi('Effective monitoring combines automated continuous monitoring with periodic independent reviews. The goal is to detect control failures quickly and verify that controls are operating as designed.', 'تجمع المراقبة الفعالة بين المراقبة المستمرة الآلية والمراجعات المستقلة الدورية. والهدف هو الكشف السريع عن حالات فشل الضوابط والتحقق من أن الضوابط تعمل وفق ما صممت له.'), question: Bi('What is the MOST effective ongoing monitoring approach?', 'ما هو منهج المراقبة المستمرة الأكثر فعالية؟'), options: [
                CaseOption(Bi('Automated continuous monitoring: Monthly reports flagging role conflicts, unusual patterns, and failed transactions', 'المراقبة المستمرة الآلية: تقارير شهرية ترصد تعارضات الأدوار والأنماط غير المعتادة والمعاملات الفاشلة'), isCorrect: true, feedback: Bi('Perfect! Continuous monitoring using data analytics provides real-time assurance that controls are working. Monthly exception reports allow you to identify and investigate anomalies promptly. This is far superior to annual audits that may miss issues for months.', 'ممتاز! توفر المراقبة المستمرة باستخدام تحليلات البيانات تأكيدا فوريا على أن الضوابط تعمل. وتتيح لك تقارير الاستثناءات الشهرية تحديد الحالات الشاذة والتحقيق فيها بسرعة. وهذا أفضل بكثير من التدقيقات السنوية التي قد تغفل عن المشكلات لأشهر.'), consequence: Bi('You implement automated monitoring dashboards. In month 3, the system flags an attempt to assign conflicting roles to a new employee, which is corrected immediately. The control environment strengthens significantly.', 'تطبق لوحات مراقبة آلية. وفي الشهر الثالث، يرصد النظام محاولة لتعيين أدوار متعارضة لموظف جديد، ويتم تصحيحها فورا. وتتعزز بيئة الرقابة بشكل كبير.')),
                CaseOption(Bi('Annual internal audit: Comprehensive testing once per year', 'التدقيق الداخلي السنوي: اختبار شامل مرة واحدة في السنة'), feedback: Bi('Annual audits are too infrequent. Issues could persist for up to 12 months before detection. More frequent monitoring is needed for critical controls like segregation of duties.', 'التدقيقات السنوية متباعدة أكثر من اللازم. فقد تستمر المشكلات حتى 12 شهرا قبل اكتشافها. وتلزم مراقبة أكثر تكرارا للضوابط الحرجة مثل الفصل بين المهام.')),
                CaseOption(Bi('Quarterly manager certification: Department heads certify their controls are working', 'إقرار المديرين الفصلي: يقر رؤساء الأقسام بأن ضوابطهم تعمل'), feedback: Bi('Self-certification is a weak control because managers may not detect their own control failures or may have incentives to report positively. Independent monitoring is more reliable.', 'الإقرار الذاتي ضابط ضعيف لأن المديرين قد لا يكتشفون حالات فشل ضوابطهم أو قد تكون لديهم حوافز للإبلاغ بشكل إيجابي. والمراقبة المستقلة أكثر موثوقية.')),
                CaseOption(Bi('Employee hotline: Encourage staff to report control violations', 'الخط الساخن للموظفين: تشجيع الموظفين على الإبلاغ عن مخالفات الضوابط'), feedback: Bi('Hotlines are valuable for whistleblower protection but are reactive. You need proactive monitoring that systematically reviews transactions and control operations before issues escalate.', 'الخطوط الساخنة قيمة لحماية المبلغين عن المخالفات لكنها ذات طابع تفاعلي. وأنت بحاجة إلى مراقبة استباقية تراجع المعاملات وعمليات الضوابط بشكل منهجي قبل تفاقم المشكلات.')),
            ]),
          ]),
        CaseScenario(id: 'procurement-controls', title: Bi('Procurement Process Controls', 'ضوابط عملية المشتريات'), role: Bi('Procurement Director', 'مدير المشتريات'), overview: Bi('You are the Procurement Director at a Saudi company planning to purchase a new financial management system for SAR 4.5 million. This is a significant IT procurement that requires competitive bidding under the company\'s procurement policy. You must ensure proper controls are in place throughout the procurement cycle to prevent favoritism, ensure value for money, and comply with policy requirements.', 'أنت مدير المشتريات في شركة سعودية تخطط لشراء نظام إدارة مالية جديد بقيمة 4.5 مليون SAR. وهذه عملية شراء تقنية كبيرة تتطلب مناقصة تنافسية بموجب سياسة المشتريات في الشركة. وعليك ضمان وجود ضوابط سليمة طوال دورة المشتريات لمنع المحاباة وضمان القيمة مقابل المال والامتثال لمتطلبات السياسة.'), finalSummary: Bi('You successfully managed a complex corporate procurement with strong controls throughout the cycle: independent evaluation committee, transparent bid opening, conflict of interest investigation, board approval, and milestone-based payment verification. This case demonstrates the importance of preventive controls (evaluation committee, conflict declarations), detective controls (scoring variance analysis, milestone verification), and corrective controls (removing conflicted evaluator, withholding payment for incomplete work). Robust procurement controls protect company funds, ensure competitive processes, and maintain stakeholder trust.', 'نجحت في إدارة عملية مشتريات مؤسسية معقدة مع ضوابط قوية طوال الدورة: لجنة تقييم مستقلة، وفتح شفاف للعطاءات، وتحقيق في تضارب المصالح، واعتماد من مجلس الإدارة، والتحقق من المدفوعات القائم على مراحل الإنجاز. وتوضح هذه الحالة أهمية الضوابط الوقائية (لجنة التقييم وإقرارات التضارب)، والضوابط الكاشفة (تحليل تباين الدرجات والتحقق من مراحل الإنجاز)، والضوابط التصحيحية (استبعاد المقيم صاحب التضارب وحجب الدفع عن العمل غير المكتمل). وتحمي ضوابط المشتريات المتينة أموال الشركة وتضمن عمليات تنافسية وتحافظ على ثقة أصحاب المصلحة.'), steps: [
            CaseStep(id: 'step1', type: CaseStepType.decision, title: Bi('Procurement Planning', 'تخطيط المشتريات'), description: Bi('The IT department has submitted a requisition for a financial management system. Before issuing the tender, you must ensure proper controls are in place for the evaluation process.', 'قدم قسم تقنية المعلومات طلب شراء لنظام إدارة مالية. وقبل إصدار المناقصة، عليك ضمان وجود ضوابط سليمة لعملية التقييم.'), data: [CaseDatum(Bi('Project Budget', 'موازنة المشروع'), 'SAR 4.5M'), CaseDatum(Bi('Expected Bidders', 'مقدمو العطاءات المتوقعون'), '5-7 firms'), CaseDatum(Bi('Evaluation Criteria', 'معايير التقييم'), 'Technical 60%, Price 40%'), CaseDatum(Bi('Timeline', 'الجدول الزمني'), '90 days')], question: Bi('What is the MOST important preventive control for the bid evaluation stage?', 'ما هو الضابط الوقائي الأهم لمرحلة تقييم العطاءات؟'), options: [
                CaseOption(Bi('Independent evaluation committee: Minimum 3 members from different departments with no conflicts of interest', 'لجنة تقييم مستقلة: 3 أعضاء على الأقل من أقسام مختلفة دون تضارب في المصالح'), isCorrect: true, feedback: Bi('Correct! An independent, multi-member evaluation committee is a critical preventive control. It prevents any single individual from manipulating the process and ensures diverse perspectives. Committee members must sign conflict of interest declarations and be independent of the procurement and requesting departments.', 'صحيح! لجنة التقييم المستقلة المتعددة الأعضاء ضابط وقائي حاسم. فهي تمنع أي فرد بمفرده من التلاعب بالعملية وتضمن تنوع وجهات النظر. ويجب على أعضاء اللجنة توقيع إقرارات تضارب المصالح وأن يكونوا مستقلين عن قسمي المشتريات والجهة الطالبة.'), consequence: Bi('You establish a 5-member committee: 2 from IT (technical expertise), 1 from Finance (budget oversight), 1 from Legal (compliance), and 1 from Audit (independence). All members sign conflict declarations.', 'تشكل لجنة من 5 أعضاء: 2 من تقنية المعلومات (الخبرة الفنية)، و 1 من المالية (الرقابة على الموازنة)، و 1 من الشؤون القانونية (الامتثال)، و 1 من التدقيق (الاستقلالية). ويوقع جميع الأعضاء إقرارات تضارب المصالح.')),
                CaseOption(Bi('Automatic selection: Always choose the lowest-priced bidder', 'الاختيار التلقائي: اختيار مقدم العطاء الأقل سعرا دائما'), feedback: Bi('Lowest price doesn\'t guarantee value for money. Corporate procurement should use quality-cost tradeoffs. A purely price-based approach can lead to poor quality, hidden costs, or non-compliant solutions. You need objective evaluation criteria.', 'السعر الأقل لا يضمن القيمة مقابل المال. وينبغي أن تستخدم مشتريات الشركات الموازنة بين الجودة والتكلفة. فالمنهج القائم على السعر وحده قد يؤدي إلى جودة متدنية أو تكاليف خفية أو حلول غير ممتثلة. وأنت بحاجة إلى معايير تقييم موضوعية.')),
                CaseOption(Bi('Assign to IT Director: Let the department head who will use the system make the selection', 'التكليف لمدير تقنية المعلومات: ترك الاختيار لرئيس القسم الذي سيستخدم النظام'), feedback: Bi('Single-person evaluation creates concentration of power and fraud risk. The requestor should not be the sole decision-maker. This violates segregation of duties and creates an opportunity for favoritism or kickbacks.', 'التقييم من شخص واحد يخلق تركيزا للسلطة ومخاطر احتيال. وينبغي ألا يكون الطالب هو صانع القرار الوحيد. فهذا ينتهك الفصل بين المهام ويخلق فرصة للمحاباة أو العمولات غير المشروعة.')),
                CaseOption(Bi('Hire external consultant to make the final vendor selection', 'الاستعانة بمستشار خارجي لاتخاذ قرار اختيار المورد النهائي'), feedback: Bi('While external expertise can be valuable for technical evaluation, the final decision should remain with the company. Consultants can advise but shouldn\'t replace internal governance. An internal committee ensures accountability.', 'رغم أن الخبرة الخارجية قد تكون قيمة في التقييم الفني، فإن القرار النهائي ينبغي أن يبقى بيد الشركة. فالمستشارون يمكنهم تقديم المشورة لكن لا ينبغي أن يحلوا محل الحوكمة الداخلية. وتضمن اللجنة الداخلية المساءلة.')),
            ]),
            CaseStep(id: 'step2', type: CaseStepType.decision, title: Bi('Bid Receipt & Opening', 'استلام العطاءات وفتحها'), description: Bi('The tender has been published. Seven firms have submitted bids by the deadline. You must ensure the bid opening process maintains integrity and prevents tampering.', 'نشرت المناقصة. وقدمت سبع شركات عطاءاتها بحلول الموعد النهائي. وعليك ضمان أن تحافظ عملية فتح العطاءات على النزاهة وتمنع التلاعب.'), context: Bi('Bid opening is a vulnerable point where bids could be altered, swapped, or leaked. Controls must ensure that all bids are accounted for, opened simultaneously, and documented in the presence of witnesses.', 'فتح العطاءات نقطة حساسة يمكن فيها تعديل العطاءات أو تبديلها أو تسريبها. ويجب أن تضمن الضوابط حصر جميع العطاءات وفتحها في آن واحد وتوثيقها بحضور شهود.'), question: Bi('Which control procedure is MOST critical during bid opening?', 'أي إجراء رقابي هو الأكثر أهمية أثناء فتح العطاءات؟'), options: [
                CaseOption(Bi('Public opening ceremony: Open all bids simultaneously in the presence of the evaluation committee, audit, and bidders (if they wish to attend)', 'جلسة فتح علنية: فتح جميع العطاءات في آن واحد بحضور لجنة التقييم والتدقيق ومقدمي العطاءات (إن رغبوا في الحضور)'), isCorrect: true, feedback: Bi('Excellent! Public bid opening is a strong transparency control that prevents bid tampering. Opening all bids simultaneously in front of multiple witnesses creates accountability and builds trust in the process. Recording bid prices publicly prevents post-opening manipulation.', 'ممتاز! الفتح العلني للعطاءات ضابط شفافية قوي يمنع التلاعب بالعطاءات. ففتح جميع العطاءات في آن واحد أمام شهود متعددين يحقق المساءلة ويبني الثقة في العملية. وتسجيل أسعار العطاءات علنا يمنع التلاعب بعد الفتح.'), consequence: Bi('All 7 bids are opened publicly. A clerk reads each bid price aloud and records it in an official log. Three bidder representatives attend as observers. The sealed bids are then secured in a locked cabinet.', 'تفتح العطاءات السبعة جميعها علنا. ويقرأ موظف كل سعر عطاء بصوت مسموع ويسجله في سجل رسمي. ويحضر ثلاثة ممثلين لمقدمي العطاءات بصفة مراقبين. ثم تحفظ العطاءات المختومة في خزانة مقفلة.')),
                CaseOption(Bi('Sequential review: Open bids one at a time as the committee evaluates each submission', 'المراجعة المتسلسلة: فتح العطاءات واحدا تلو الآخر بينما تقيم اللجنة كل عطاء'), feedback: Bi('Sequential opening creates opportunities for bias. Evaluators might be influenced by earlier bids when reviewing later ones. All bids should be opened simultaneously and evaluated independently to ensure fair comparison.', 'الفتح المتسلسل يخلق فرصا للتحيز. فقد يتأثر المقيمون بالعطاءات المبكرة عند مراجعة العطاءات اللاحقة. وينبغي فتح جميع العطاءات في آن واحد وتقييمها بشكل مستقل لضمان مقارنة عادلة.')),
                CaseOption(Bi('Confidential opening: Procurement staff open bids privately to protect bidder confidentiality', 'الفتح السري: يفتح موظفو المشتريات العطاءات على انفراد لحماية سرية مقدمي العطاءات'), feedback: Bi('Private opening increases fraud risk. While bid details should be confidential during evaluation, the opening itself should be witnessed to prevent tampering. Transparency at the opening stage protects integrity.', 'الفتح السري يزيد من مخاطر الاحتيال. ورغم أن تفاصيل العطاءات ينبغي أن تبقى سرية أثناء التقييم، فإن الفتح نفسه ينبغي أن يتم بحضور شهود لمنع التلاعب. والشفافية في مرحلة الفتح تحمي النزاهة.')),
                CaseOption(Bi('Allow early access: Let the evaluation committee review bids as they arrive to save time', 'السماح بالوصول المبكر: ترك لجنة التقييم تراجع العطاءات فور وصولها لتوفير الوقت'), feedback: Bi('Early access creates serious risks: information could leak to late bidders, giving them an unfair advantage, or committee members could be influenced by early submissions. All bids must remain sealed until the official opening.', 'الوصول المبكر يخلق مخاطر جسيمة: فقد تتسرب المعلومات إلى مقدمي العطاءات المتأخرين مما يمنحهم ميزة غير عادلة، أو قد يتأثر أعضاء اللجنة بالعطاءات المبكرة. ويجب أن تبقى جميع العطاءات مختومة حتى الفتح الرسمي.')),
            ]),
            CaseStep(id: 'step3', type: CaseStepType.decision, title: Bi('Evaluation Process', 'عملية التقييم'), description: Bi('The evaluation committee is now scoring the seven bids. Each committee member independently evaluates technical criteria (60%) and price (40%). You discover that one committee member, Khalid, has given consistently high scores to Vendor C across all criteria, while rating all other vendors very low.', 'تقوم لجنة التقييم الآن بتقييم العطاءات السبعة. ويقيم كل عضو في اللجنة بشكل مستقل المعايير الفنية (60%) والسعر (40%). وتكتشف أن أحد أعضاء اللجنة، Khalid، منح Vendor C درجات مرتفعة باستمرار في جميع المعايير، بينما قيم جميع الموردين الآخرين بدرجات منخفضة جدا.'), data: [CaseDatum(Bi('Vendor C Score (Khalid)', 'درجة Vendor C (Khalid)'), '95/100'), CaseDatum(Bi('Vendor C Avg (Other Members)', 'متوسط Vendor C (الأعضاء الآخرون)'), '72/100'), CaseDatum(Bi('Score Standard Deviation', 'الانحراف المعياري للدرجات'), '18 points'), CaseDatum(Bi('Vendor C Price Rank', 'ترتيب Vendor C من حيث السعر'), '3rd of 7')], question: Bi('How should you address this potential bias in the evaluation?', 'كيف ينبغي أن تعالج هذا التحيز المحتمل في التقييم؟'), options: [
                CaseOption(Bi('Investigate conflict of interest: Interview Khalid privately to determine if he has undisclosed relationships with Vendor C', 'التحقيق في تضارب المصالح: مقابلة Khalid على انفراد لتحديد ما إذا كانت لديه علاقات غير معلنة مع Vendor C'), isCorrect: true, feedback: Bi('Correct! Extreme scoring variance is a red flag for potential conflicts of interest. You must investigate whether Khalid has personal, financial, or professional relationships with Vendor C that he failed to disclose. If a conflict exists, his scores should be excluded and he may face disciplinary action.', 'صحيح! التباين الشديد في الدرجات مؤشر تحذيري على تضارب محتمل في المصالح. وعليك التحقيق فيما إذا كانت لدى Khalid علاقات شخصية أو مالية أو مهنية مع Vendor C لم يفصح عنها. وإذا وجد تضارب، فينبغي استبعاد درجاته وقد يواجه إجراءات تأديبية.'), consequence: Bi('Your investigation reveals that Khalid\'s cousin works as a sales manager at Vendor C. Khalid failed to disclose this on his conflict declaration. You remove him from the committee and re-score without his input. Vendor B emerges as the winner.', 'يكشف تحقيقك أن ابن عم Khalid يعمل مدير مبيعات لدى Vendor C. ولم يفصح Khalid عن ذلك في إقرار تضارب المصالح. فتقوم باستبعاده من اللجنة وإعادة التقييم دون مشاركته. ويبرز Vendor B فائزا.')),
                CaseOption(Bi('Statistical normalization: Adjust all scores to remove outliers and create a normalized average', 'التسوية الإحصائية: تعديل جميع الدرجات لإزالة القيم الشاذة وإنشاء متوسط مسوى'), feedback: Bi('Statistical manipulation masks the underlying problem rather than addressing it. If bias exists, you need to identify and remove the source of bias (the conflicted evaluator), not adjust scores mathematically.', 'التلاعب الإحصائي يخفي المشكلة الجوهرية بدلا من معالجتها. فإذا وجد تحيز، فأنت بحاجة إلى تحديد مصدر التحيز وإزالته (المقيم صاحب التضارب)، لا تعديل الدرجات حسابيا.')),
                CaseOption(Bi('Accept the variance: Different evaluators have different perspectives; averaging will balance it out', 'قبول التباين: للمقيمين المختلفين وجهات نظر مختلفة، والمتوسط سيوازنها'), feedback: Bi('Ignoring significant variance is negligent. While some variation is normal, a 23-point gap on one vendor is suspicious and suggests potential bias or conflict of interest that must be investigated.', 'تجاهل التباين الكبير إهمال. ورغم أن بعض التباين طبيعي، فإن فجوة قدرها 23 نقطة على مورد واحد مثيرة للريبة وتشير إلى تحيز محتمل أو تضارب مصالح يجب التحقيق فيه.')),
                CaseOption(Bi('Committee discussion: Bring all members together to discuss scores and reach consensus', 'مناقشة اللجنة: جمع جميع الأعضاء لمناقشة الدرجات والوصول إلى توافق'), feedback: Bi('Group discussion before investigating bias could allow a conflicted member to pressure others or contaminate independent judgment. Individual scoring is a control; you shouldn\'t undermine it without first determining if a conflict exists.', 'قد تتيح المناقشة الجماعية قبل التحقيق في التحيز لعضو صاحب تضارب الضغط على الآخرين أو التأثير في الحكم المستقل. والتقييم الفردي ضابط، ولا ينبغي أن تقوضه قبل تحديد ما إذا كان هناك تضارب.')),
            ]),
            CaseStep(id: 'step4', type: CaseStepType.recommendation, title: Bi('Contract Award Approval', 'اعتماد ترسية العقد'), description: Bi('After removing the conflicted evaluator, Vendor B has won with a score of 84/100 and a bid price of SAR 4.2 million. The evaluation committee has documented its recommendation. Now you must obtain proper approval before awarding the contract.', 'بعد استبعاد المقيم صاحب التضارب، فاز Vendor B بدرجة 84/100 وبسعر عطاء قدره 4.2 مليون SAR. ووثقت لجنة التقييم توصيتها. والآن عليك الحصول على الاعتماد السليم قبل ترسية العقد.'), context: Bi('Corporate procurement policies require approval hierarchies based on contract value. Large contracts typically require board or executive committee approval. The approval authority must be independent of the evaluation committee to provide oversight.', 'تتطلب سياسات مشتريات الشركات تسلسلات هرمية للاعتماد بناء على قيمة العقد. وتتطلب العقود الكبيرة عادة اعتماد مجلس الإدارة أو اللجنة التنفيذية. ويجب أن تكون سلطة الاعتماد مستقلة عن لجنة التقييم لتوفير الرقابة.'), question: Bi('What approval process is required for this SAR 4.2 million contract award?', 'ما هي عملية الاعتماد المطلوبة لترسية هذا العقد البالغ 4.2 مليون SAR؟'), options: [
                CaseOption(Bi('Board approval: Submit to the company\'s board with full evaluation documentation and legal review', 'اعتماد مجلس الإدارة: الرفع إلى مجلس إدارة الشركة مع وثائق التقييم الكاملة والمراجعة القانونية'), isCorrect: true, feedback: Bi('Excellent! A SAR 4.2 million contract requires board-level approval under most companies\' delegation-of-authority policies. The board provides independent oversight of the procurement process. You should submit: evaluation committee report, technical and financial analysis, conflict resolution documentation, and legal clearance.', 'ممتاز! العقد البالغ 4.2 مليون SAR يتطلب اعتمادا على مستوى مجلس الإدارة بموجب سياسات تفويض الصلاحيات في معظم الشركات. ويوفر المجلس رقابة مستقلة على عملية المشتريات. وينبغي أن ترفع: تقرير لجنة التقييم، والتحليل الفني والمالي، ووثائق معالجة تضارب المصالح، والإجازة القانونية.'), consequence: Bi('The board reviews your submission and approves the award to Vendor B. They commend your investigation of the conflict of interest and ask you to present lessons learned to other procurement staff.', 'يراجع المجلس ما رفعته ويعتمد الترسية على Vendor B. ويشيدون بتحقيقك في تضارب المصالح ويطلبون منك عرض الدروس المستفادة على بقية موظفي المشتريات.')),
                CaseOption(Bi('Director approval: You approve the contract as Procurement Director since you led the process', 'اعتماد المدير: أنت تعتمد العقد بصفتك مدير المشتريات لأنك قدت العملية'), feedback: Bi('Self-approval violates segregation of duties. The person managing the procurement process should not be the final approver. Contracts of this size require higher-level approval (board or minister) to ensure independent oversight.', 'الاعتماد الذاتي ينتهك الفصل بين المهام. فالشخص الذي يدير عملية المشتريات ينبغي ألا يكون المعتمد النهائي. والعقود بهذا الحجم تتطلب اعتمادا على مستوى أعلى (مجلس الإدارة) لضمان الرقابة المستقلة.')),
                CaseOption(Bi('Committee approval: The evaluation committee\'s recommendation is sufficient; no additional approval needed', 'اعتماد اللجنة: توصية لجنة التقييم كافية، ولا حاجة لاعتماد إضافي'), feedback: Bi('The evaluation committee makes a recommendation, but final award authority must rest with a separate, higher-level body. This separation ensures independent review and accountability for large expenditures.', 'تقدم لجنة التقييم توصية، لكن سلطة الترسية النهائية يجب أن تكون بيد جهة منفصلة أعلى مستوى. ويضمن هذا الفصل مراجعة مستقلة ومساءلة عن النفقات الكبيرة.')),
                CaseOption(Bi('Finance approval: Route to the CFO for budget confirmation', 'اعتماد المالية: الإحالة إلى المدير المالي لتأكيد الموازنة'), feedback: Bi('While budget confirmation is necessary, it\'s not sufficient for final approval. The CFO should verify funds are available, but governance requires board approval for contracts of this magnitude.', 'رغم أن تأكيد الموازنة ضروري، فإنه غير كاف للاعتماد النهائي. وينبغي أن يتحقق المدير المالي من توافر الأموال، لكن الحوكمة تتطلب اعتماد مجلس الإدارة للعقود بهذا الحجم.')),
            ]),
            CaseStep(id: 'step5', type: CaseStepType.recommendation, title: Bi('Contract Management & Monitoring', 'إدارة العقد ومراقبته'), description: Bi('The contract with Vendor B has been signed. The implementation will take 12 months with payments tied to milestones: 30% upfront, 40% at system testing, 30% at go-live. You must establish controls to monitor contract performance and ensure value is received before payments are made.', 'وقع العقد مع Vendor B. وسيستغرق التنفيذ 12 شهرا مع ربط المدفوعات بمراحل إنجاز: 30% مقدما، و 40% عند اختبار النظام، و 30% عند التشغيل الفعلي. وعليك إنشاء ضوابط لمراقبة أداء العقد وضمان تحقق القيمة قبل صرف المدفوعات.'), data: [CaseDatum(Bi('Contract Value', 'قيمة العقد'), 'SAR 4.2M'), CaseDatum(Bi('Duration', 'المدة'), '12 months'), CaseDatum(Bi('Payment Milestones', 'مراحل الدفع'), '3 payments'), CaseDatum(Bi('Contractual Deliverables', 'المخرجات التعاقدية'), '15 items')], question: Bi('What is the MOST important control for ongoing contract management?', 'ما هو الضابط الأهم لإدارة العقد المستمرة؟'), options: [
                CaseOption(Bi('Independent milestone verification: Require IT and Audit to certify each deliverable is complete before releasing payment', 'التحقق المستقل من مراحل الإنجاز: اشتراط أن يقر قسم تقنية المعلومات والتدقيق باكتمال كل مخرج قبل صرف الدفعة'), isCorrect: true, feedback: Bi('Perfect! Independent verification of deliverables before payment is a critical control. The IT department verifies technical acceptance, and Audit confirms compliance with contract terms. This "pay for performance" approach ensures the company receives value before disbursing funds and prevents paying for incomplete work.', 'ممتاز! التحقق المستقل من المخرجات قبل الدفع ضابط حاسم. فقسم تقنية المعلومات يتحقق من القبول الفني، والتدقيق يؤكد الامتثال لشروط العقد. ويضمن منهج الدفع مقابل الأداء هذا حصول الشركة على القيمة قبل صرف الأموال ويمنع الدفع مقابل عمل غير مكتمل.'), consequence: Bi('The verification process works well. At the 40% milestone, Audit discovers that 2 of 6 required deliverables are incomplete. You withhold payment until Vendor B completes them. The project finishes on time and budget with all deliverables met.', 'تعمل عملية التحقق بشكل جيد. وعند مرحلة الـ 40%، يكتشف التدقيق أن 2 من 6 مخرجات مطلوبة غير مكتملة. فتحجب الدفعة حتى يكملها Vendor B. وينتهي المشروع في الوقت المحدد وضمن الموازنة مع تحقيق جميع المخرجات.')),
                CaseOption(Bi('Schedule-based payment: Release payments automatically on the scheduled milestone dates', 'الدفع حسب الجدول: صرف المدفوعات تلقائيا في تواريخ مراحل الإنجاز المجدولة'), feedback: Bi('Automatic payments without verifying deliverables create risk. The vendor might miss milestones but still receive payment. You need to confirm work is complete before paying. Payment should be tied to performance, not just time.', 'المدفوعات التلقائية دون التحقق من المخرجات تخلق مخاطر. فقد يخفق المورد في تحقيق مراحل الإنجاز ومع ذلك يتلقى الدفعة. وأنت بحاجة إلى تأكيد اكتمال العمل قبل الدفع. وينبغي ربط الدفع بالأداء، لا بالوقت فحسب.')),
                CaseOption(Bi('Vendor self-certification: Accept the vendor\'s declaration that milestones are complete', 'الإقرار الذاتي للمورد: قبول إقرار المورد باكتمال مراحل الإنجاز'), feedback: Bi('Vendor self-certification is a weak control because of inherent conflict of interest. The vendor has a financial incentive to declare completion even if work is incomplete. You need independent verification by the company.', 'الإقرار الذاتي للمورد ضابط ضعيف بسبب تضارب المصالح المتأصل. فللمورد حافز مالي لإعلان الاكتمال حتى لو كان العمل غير مكتمل. وأنت بحاجة إلى تحقق مستقل من قبل الشركة.')),
                CaseOption(Bi('Quarterly financial review: Have Finance department review invoices quarterly', 'المراجعة المالية الفصلية: أن يراجع قسم المالية الفواتير كل ربع سنة'), feedback: Bi('Financial review of invoices is necessary but insufficient. You also need technical review to confirm deliverables meet specifications and contractual requirements. Finance verifies amounts; IT/Audit verify value and compliance.', 'المراجعة المالية للفواتير ضرورية لكنها غير كافية. فأنت بحاجة أيضا إلى مراجعة فنية لتأكيد أن المخرجات تطابق المواصفات والمتطلبات التعاقدية. فالمالية تتحقق من المبالغ، بينما يتحقق قسم تقنية المعلومات والتدقيق من القيمة والامتثال.')),
            ]),
          ]),
        CaseScenario(id: 'fraud-detection', title: Bi('Fraud Detection & Investigation', 'كشف الاحتيال والتحقيق فيه'), role: Bi('Chief Internal Auditor', 'رئيس التدقيق الداخلي'), overview: Bi('You are the Chief Internal Auditor at a Saudi company with 250 employees. Your data analytics team has flagged unusual patterns in employee expense reports and travel claims over the past 9 months. The analytics show that Dr. Sarah Al-Qahtani, Director of International Relations, has submitted 23 travel expense claims totaling SAR 340,000 - significantly higher than her peers. You must investigate whether fraud or abuse has occurred.', 'أنت رئيس التدقيق الداخلي في شركة سعودية تضم 250 موظفا. وقد رصد فريق تحليلات البيانات لديك أنماطا غير معتادة في تقارير مصروفات الموظفين ومطالبات السفر خلال الأشهر الـ 9 الماضية. وتظهر التحليلات أن Dr. Sarah Al-Qahtani، مديرة العلاقات الدولية، قدمت 23 مطالبة مصروفات سفر بإجمالي 340,000 SAR - أعلى بكثير من أقرانها. وعليك التحقيق فيما إذا كان قد وقع احتيال أو إساءة استخدام.'), finalSummary: Bi('You successfully detected, investigated, and resolved an employee expense fraud case using data analytics, systematic evidence gathering, proper escalation, and evidence-based interviewing. The case demonstrates the fraud triangle: Sarah had (1) opportunity (weak controls), (2) pressure (financial need), and (3) rationalization ("medical expenses"). Your corrective actions addressed all three: automated analytics remove opportunity, early detection reduces pressure to escalate fraud, and clear consequences (reimbursement, resignation, possible prosecution) eliminate rationalization. This case shows why preventive controls (continuous monitoring) are superior to detective controls (annual audits) and why strong tone at the top (swift response to fraud) is critical for organizational integrity.', 'نجحت في كشف حالة احتيال في مصروفات موظف والتحقيق فيها وحلها باستخدام تحليلات البيانات والجمع المنهجي للأدلة والتصعيد السليم والمقابلة القائمة على الأدلة. وتوضح الحالة مثلث الاحتيال: فقد توفرت لدى Sarah (1) الفرصة (ضعف الضوابط)، (2) الضغط (الحاجة المالية)، (3) التبرير (النفقات الطبية). وعالجت إجراءاتك التصحيحية العناصر الثلاثة جميعها: فالتحليلات الآلية تزيل الفرصة، والكشف المبكر يقلل من الضغط لتصعيد الاحتيال، والعواقب الواضحة (السداد والاستقالة واحتمال الملاحقة القضائية) تلغي التبرير. وتبين هذه الحالة لماذا تتفوق الضوابط الوقائية (المراقبة المستمرة) على الضوابط الكاشفة (التدقيقات السنوية)، ولماذا يعد توجه القيادة العليا القوي (الاستجابة السريعة للاحتيال) بالغ الأهمية لنزاهة المؤسسة.'), steps: [
            CaseStep(id: 'step1', type: CaseStepType.analysis, title: Bi('Initial Red Flag Analysis', 'التحليل الأولي للمؤشرات التحذيرية'), description: Bi('Your analytics system has generated an alert based on expense patterns. You review the comparative data for Directors over the past 9 months.', 'أصدر نظام التحليلات لديك تنبيها بناء على أنماط المصروفات. وتراجع البيانات المقارنة للمديرين خلال الأشهر الـ 9 الماضية.'), data: [CaseDatum(Bi('Sarah - Claims', 'Sarah - المطالبات'), '23 trips'), CaseDatum(Bi('Sarah - Total', 'Sarah - الإجمالي'), 'SAR 340k'), CaseDatum(Bi('Peer Average - Claims', 'متوسط الأقران - المطالبات'), '8 trips'), CaseDatum(Bi('Peer Average - Total', 'متوسط الأقران - الإجمالي'), 'SAR 95k'), CaseDatum(Bi('Sarah - Weekend Stays', 'Sarah - الإقامات في عطلة نهاية الأسبوع'), '16 claims'), CaseDatum(Bi('Duplicate Receipts', 'الإيصالات المكررة'), '4 found')], question: Bi('Which red flag is MOST indicative of potential fraud?', 'أي مؤشر تحذيري هو الأكثر دلالة على احتيال محتمل؟'), options: [
                CaseOption(Bi('High volume: Sarah has 3x more trips than her peers', 'الحجم المرتفع: عدد رحلات Sarah أكبر بثلاثة أضعاف من أقرانها'), feedback: Bi('While high volume is notable, it might be legitimate if her role requires more international travel. High volume alone isn\'t proof of fraud - you need to look for patterns that suggest intentional deception.', 'رغم أن الحجم المرتفع لافت، فقد يكون مشروعا إذا كان دورها يتطلب سفرا دوليا أكثر. والحجم المرتفع وحده ليس دليلا على الاحتيال - فأنت بحاجة إلى البحث عن أنماط تشير إلى خداع متعمد.')),
                CaseOption(Bi('Personal benefit: 16 of 23 trips include weekend hotel stays at tourist destinations', 'منفعة شخصية: 16 من 23 رحلة تتضمن إقامات فندقية في عطلة نهاية الأسبوع في وجهات سياحية'), feedback: Bi('Weekend stays are suspicious but could have legitimate business purposes (conferences that span weekends). This is a yellow flag that warrants investigation but isn\'t the strongest indicator. Look for evidence of fabrication or duplication.', 'الإقامات في عطلة نهاية الأسبوع مثيرة للريبة لكن قد تكون لها أغراض عمل مشروعة (مؤتمرات تمتد عبر عطلة نهاية الأسبوع). وهذا مؤشر تحذيري أصفر يستدعي التحقيق لكنه ليس الأقوى دلالة. فابحث عن أدلة التلفيق أو التكرار.')),
                CaseOption(Bi('Duplicate receipts: 4 hotel receipts appear on multiple expense reports with different dates', 'الإيصالات المكررة: 4 إيصالات فندقية تظهر في تقارير مصروفات متعددة بتواريخ مختلفة'), isCorrect: true, feedback: Bi('Correct! Duplicate receipts with altered dates are a strong indicator of fraud. This suggests intentional fabrication - Sarah is likely reusing the same receipt to claim reimbursement multiple times. This is clear evidence of deception, not just overspending or poor judgment.', 'صحيح! الإيصالات المكررة بتواريخ معدلة مؤشر قوي على الاحتيال. وهذا يشير إلى تلفيق متعمد - فمن المرجح أن Sarah تعيد استخدام الإيصال نفسه للمطالبة بالسداد عدة مرات. وهذا دليل واضح على الخداع، لا مجرد إفراط في الإنفاق أو سوء تقدير.'), consequence: Bi('You analyze the 4 duplicate receipts: same hotel invoice numbers, same amounts, but submitted for different travel dates. The receipt images have been manipulated using photo editing software.', 'تحلل الإيصالات المكررة الأربعة: أرقام فواتير فندقية متطابقة، ومبالغ متطابقة، لكنها مقدمة عن تواريخ سفر مختلفة. وقد جرى التلاعب بصور الإيصالات باستخدام برامج تحرير الصور.')),
                CaseOption(Bi('Dollar variance: Sarah\'s total is SAR 340k vs. peer average of SAR 95k', 'التباين في المبالغ: إجمالي Sarah يبلغ 340k SAR مقابل متوسط أقرانها البالغ 95k SAR'), feedback: Bi('High total spending is a symptom but doesn\'t prove fraud. Her role might legitimately require more travel. Focus on patterns that indicate intentional deception (duplicates, fabrication, conflicts of interest) rather than absolute amounts.', 'ارتفاع إجمالي الإنفاق عرض لكنه لا يثبت الاحتيال. فقد يتطلب دورها بشكل مشروع سفرا أكثر. ركز على الأنماط التي تدل على خداع متعمد (التكرارات والتلفيق وتضارب المصالح) بدلا من المبالغ المطلقة.')),
            ]),
            CaseStep(id: 'step2', type: CaseStepType.decision, title: Bi('Evidence Collection', 'جمع الأدلة'), description: Bi('You have identified duplicate receipts as a red flag. Now you must gather additional evidence to determine the scope of the fraud and build a case. You want to avoid alerting Sarah prematurely.', 'حددت الإيصالات المكررة كمؤشر تحذيري. والآن عليك جمع أدلة إضافية لتحديد نطاق الاحتيال وبناء قضية. وترغب في تجنب تنبيه Sarah قبل الأوان.'), context: Bi('Fraud investigations require maintaining confidentiality, preserving evidence, and following a systematic approach. Premature interviews can allow perpetrators to destroy evidence or coordinate false explanations.', 'تتطلب تحقيقات الاحتيال الحفاظ على السرية وصون الأدلة واتباع منهج منظم. فالمقابلات المبكرة قد تتيح للجناة إتلاف الأدلة أو تنسيق تفسيرات كاذبة.'), question: Bi('What is the MOST appropriate next investigative step?', 'ما هي الخطوة التحقيقية التالية الأنسب؟'), options: [
                CaseOption(Bi('Confront immediately: Interview Sarah and ask her to explain the duplicate receipts', 'المواجهة الفورية: مقابلة Sarah وطلب تفسيرها للإيصالات المكررة'), feedback: Bi('Premature confrontation is a mistake. If Sarah is committing fraud, early warning could allow her to destroy evidence, create false documentation, or coordinate stories with accomplices. Gather all evidence first, then interview.', 'المواجهة المبكرة خطأ. فإذا كانت Sarah ترتكب احتيالا، فقد يتيح لها التحذير المبكر إتلاف الأدلة أو إنشاء وثائق كاذبة أو تنسيق الروايات مع شركاء. اجمع كل الأدلة أولا، ثم أجر المقابلة.')),
                CaseOption(Bi('Comprehensive document review: Analyze all 23 expense reports for additional anomalies (more duplicates, vendor patterns, approval irregularities)', 'مراجعة شاملة للوثائق: تحليل جميع تقارير المصروفات الـ 23 بحثا عن حالات شاذة إضافية (مزيد من التكرارات وأنماط الموردين ومخالفات الاعتماد)'), isCorrect: true, feedback: Bi('Excellent! Systematic document analysis allows you to understand the full scope of fraud before alerting the subject. Look for: more duplicate receipts, fabricated vendors, altered documents, payments to related parties, approval bypass, and timeline inconsistencies. This builds a complete evidentiary foundation.', 'ممتاز! يتيح لك التحليل المنهجي للوثائق فهم النطاق الكامل للاحتيال قبل تنبيه الشخص المعني. ابحث عن: مزيد من الإيصالات المكررة، وموردين ملفقين، ووثائق معدلة، ومدفوعات لأطراف ذات علاقة، وتجاوز الاعتماد، وتناقضات في التسلسل الزمني. وهذا يبني أساسا استدلاليا متكاملا.'), consequence: Bi('Your detailed analysis reveals 12 duplicate receipts (not just 4), 8 claims for conferences that never occurred, and 5 taxi receipts from a company owned by Sarah\'s husband. Total fraudulent claims: SAR 180,000.', 'يكشف تحليلك التفصيلي عن 12 إيصالا مكررا (لا 4 فقط)، و 8 مطالبات عن مؤتمرات لم تنعقد قط، و 5 إيصالات أجرة من شركة يملكها زوج Sarah. وإجمالي المطالبات الاحتيالية: 180,000 SAR.')),
                CaseOption(Bi('Interview Sarah\'s manager to ask if the travel was authorized', 'مقابلة مدير Sarah للاستفسار عما إذا كان السفر مصرحا به'), feedback: Bi('Interviewing the manager might alert Sarah if the manager mentions the inquiry. Additionally, the manager might be complicit or negligent in approving false claims. Review documentary evidence first, then conduct interviews once you understand the full picture.', 'قد تنبه مقابلة المدير Sarah إذا ذكر المدير الاستفسار. كما قد يكون المدير متواطئا أو مهملا في اعتماد المطالبات الكاذبة. راجع الأدلة الوثائقية أولا، ثم أجر المقابلات بعد أن تفهم الصورة الكاملة.')),
                CaseOption(Bi('Contact hotels directly to verify Sarah\'s stays and receipt authenticity', 'التواصل مع الفنادق مباشرة للتحقق من إقامات Sarah وصحة الإيصالات'), feedback: Bi('External verification is valuable but should come after internal document analysis. Start by reviewing what you have access to internally (all expense reports, receipts, approvals). External inquiries can follow once you know what to verify.', 'التحقق الخارجي قيم لكن ينبغي أن يأتي بعد التحليل الداخلي للوثائق. ابدأ بمراجعة ما يمكنك الوصول إليه داخليا (جميع تقارير المصروفات والإيصالات والاعتمادات). ويمكن أن تلي ذلك الاستفسارات الخارجية بمجرد أن تعرف ما يلزم التحقق منه.')),
            ]),
            CaseStep(id: 'step3', type: CaseStepType.stakeholder, title: Bi('Stakeholder Notification', 'إبلاغ أصحاب المصلحة'), description: Bi('Your investigation has uncovered evidence of SAR 180,000 in fraudulent expense claims. You have documented 12 duplicate receipts, 8 fictitious conferences, and payments to a related-party vendor. Now you must decide how to escalate this finding.', 'كشف تحقيقك عن أدلة على مطالبات مصروفات احتيالية بقيمة 180,000 SAR. وقد وثقت 12 إيصالا مكررا، و 8 مؤتمرات وهمية، ومدفوعات لمورد طرف ذي علاقة. والآن عليك أن تقرر كيفية تصعيد هذا الاكتشاف.'), data: [CaseDatum(Bi('Estimated Fraud', 'الاحتيال المقدر'), 'SAR 180k'), CaseDatum(Bi('Evidence Items', 'عناصر الأدلة'), '25 documents'), CaseDatum(Bi('Time Period', 'الفترة الزمنية'), '9 months'), CaseDatum(Bi('Sarah\'s Tenure', 'مدة خدمة Sarah'), '4 years')], question: Bi('Who should you notify first about the suspected fraud?', 'من الذي ينبغي أن تبلغه أولا عن الاحتيال المشتبه به؟'), options: [
                CaseOption(Bi('Executive management: Brief the CEO on the findings before taking further action', 'الإدارة التنفيذية: إطلاع الرئيس التنفيذي على النتائج قبل اتخاذ أي إجراء آخر'), isCorrect: true, feedback: Bi('Correct! Significant fraud allegations involving a senior manager require immediate notification of executive management. The CEO needs to be informed before: (1) interviews that could escalate the situation, (2) external reporting, or (3) potential media exposure. Management will decide on next steps, including legal counsel, HR, and possible police involvement.', 'صحيح! تتطلب اتهامات الاحتيال الجوهرية التي تشمل مديرا كبيرا إبلاغ الإدارة التنفيذية فورا. فالرئيس التنفيذي بحاجة إلى الإبلاغ قبل: (1) المقابلات التي قد تصعد الموقف، (2) الإبلاغ الخارجي، (3) الانكشاف الإعلامي المحتمل. وستقرر الإدارة الخطوات التالية، بما في ذلك المستشار القانوني والموارد البشرية واحتمال إشراك الشرطة.'), consequence: Bi('The CEO convenes an emergency meeting with you, Legal, HR, and the Board Chair. They authorize you to continue the investigation and retain external forensic auditors. They also place Sarah on administrative leave.', 'يعقد الرئيس التنفيذي اجتماعا طارئا معك ومع الشؤون القانونية والموارد البشرية ورئيس مجلس الإدارة. ويأذنون لك بمواصلة التحقيق والاستعانة بمدققين جنائيين خارجيين. كما يضعون Sarah في إجازة إدارية.')),
                CaseOption(Bi('Human Resources: Report to HR for employee disciplinary process', 'الموارد البشرية: الإبلاغ إلى الموارد البشرية لإجراء التأديب الوظيفي'), feedback: Bi('HR will eventually be involved, but fraud of this magnitude requires executive management notification first. The CEO needs to know about significant fraud before HR takes employment actions. Executive leadership may need to involve legal counsel or law enforcement.', 'ستشارك الموارد البشرية في نهاية المطاف، لكن الاحتيال بهذا الحجم يتطلب إبلاغ الإدارة التنفيذية أولا. فالرئيس التنفيذي بحاجة إلى معرفة الاحتيال الجوهري قبل أن تتخذ الموارد البشرية إجراءات وظيفية. وقد تحتاج القيادة التنفيذية إلى إشراك المستشار القانوني أو جهات إنفاذ القانون.')),
                CaseOption(Bi('Law enforcement: File a police report immediately', 'جهات إنفاذ القانون: تقديم بلاغ للشرطة فورا'), feedback: Bi('Police involvement may be appropriate, but executive management should make that decision, not Internal Audit. Report to leadership first, then they can determine whether to involve law enforcement based on legal advice and organizational policy.', 'قد يكون إشراك الشرطة مناسبا، لكن ينبغي أن تتخذ الإدارة التنفيذية هذا القرار، لا التدقيق الداخلي. أبلغ القيادة أولا، ثم يمكنها تحديد ما إذا كانت ستشرك جهات إنفاذ القانون بناء على المشورة القانونية وسياسة المؤسسة.')),
                CaseOption(Bi('Audit Committee: Present findings at the next quarterly board meeting', 'لجنة المراجعة: عرض النتائج في اجتماع مجلس الإدارة الفصلي القادم'), feedback: Bi('The Audit Committee should be informed, but waiting for a quarterly meeting delays response to active fraud. Immediate notification of executive management is required for time-sensitive issues. The Audit Committee can be briefed after immediate actions are taken.', 'ينبغي إبلاغ لجنة المراجعة، لكن انتظار اجتماع فصلي يؤخر الاستجابة لاحتيال قائم. ويلزم إبلاغ الإدارة التنفيذية فورا للمسائل الحساسة زمنيا. ويمكن إطلاع لجنة المراجعة بعد اتخاذ الإجراءات الفورية.')),
            ]),
            CaseStep(id: 'step4', type: CaseStepType.decision, title: Bi('Fraud Interview', 'مقابلة الاحتيال'), description: Bi('With management authorization, you are ready to interview Sarah. External forensic auditors will assist. Sarah has been placed on administrative leave and asked to meet with the investigation team. You must conduct the interview carefully to obtain a confession or explanation while protecting employee rights.', 'بإذن من الإدارة، أصبحت مستعدا لمقابلة Sarah. وسيساعد مدققون جنائيون خارجيون. وقد وضعت Sarah في إجازة إدارية وطلب منها الاجتماع بفريق التحقيق. وعليك إجراء المقابلة بعناية للحصول على اعتراف أو تفسير مع حماية حقوق الموظف.'), context: Bi('Fraud interviews should follow a structured approach: start with open questions, present evidence incrementally, observe reactions, and seek admission or explanation. The interview should be documented and may be used in legal proceedings.', 'ينبغي أن تتبع مقابلات الاحتيال منهجا منظما: البدء بأسئلة مفتوحة، وعرض الأدلة تدريجيا، ومراقبة ردود الأفعال، والسعي للحصول على إقرار أو تفسير. وينبغي توثيق المقابلة وقد تستخدم في الإجراءات القانونية.'), question: Bi('What is the BEST approach for conducting the fraud interview?', 'ما هو أفضل منهج لإجراء مقابلة الاحتيال؟'), options: [
                CaseOption(Bi('Accusatory approach: Start by telling Sarah she committed fraud and demand an immediate confession', 'المنهج الاتهامي: البدء بإخبار Sarah أنها ارتكبت احتيالا وطلب اعتراف فوري'), feedback: Bi('Accusatory interviews often cause subjects to become defensive and stop cooperating. A more effective approach is to start with open questions, present evidence, and allow the subject to provide explanations. This can lead to admissions or reveal additional fraud.', 'كثيرا ما تدفع المقابلات الاتهامية الأشخاص إلى اتخاذ موقف دفاعي والتوقف عن التعاون. والمنهج الأكثر فعالية هو البدء بأسئلة مفتوحة، وعرض الأدلة، وإتاحة الفرصة للشخص لتقديم تفسيرات. وقد يؤدي ذلك إلى إقرارات أو يكشف احتيالا إضافيا.')),
                CaseOption(Bi('Evidence-based interview: Present evidence systematically, starting with minor issues and building to the most serious fraud allegations', 'المقابلة القائمة على الأدلة: عرض الأدلة بشكل منهجي، بدءا من المسائل الطفيفة وصولا إلى أخطر اتهامات الاحتيال'), isCorrect: true, feedback: Bi('Excellent! The evidence-based approach starts with less serious issues to establish a pattern of dishonesty, then escalates to major fraud. This technique often leads to admissions because the subject realizes the evidence is overwhelming. Document the interview, have witnesses present, and give Sarah opportunities to explain.', 'ممتاز! يبدأ المنهج القائم على الأدلة بالمسائل الأقل خطورة لإثبات نمط من عدم الأمانة، ثم يتصاعد إلى الاحتيال الكبير. وكثيرا ما تؤدي هذه التقنية إلى إقرارات لأن الشخص يدرك أن الأدلة دامغة. وثق المقابلة، واحرص على وجود شهود، وامنح Sarah فرصا للتفسير.'), consequence: Bi('You present the evidence methodically. When shown the duplicate receipts, Sarah initially claims "administrative errors." When confronted with the related-party taxi vendor, she admits to systematic fraud, saying she needed money for her daughter\'s medical treatment. She agrees to reimburse SAR 180,000.', 'تعرض الأدلة بشكل منهجي. وعندما تعرض عليها الإيصالات المكررة، تدعي Sarah في البداية أنها أخطاء إدارية. وعندما تواجه بمورد الأجرة الطرف ذي العلاقة، تعترف باحتيال منهجي، قائلة إنها كانت بحاجة إلى المال للعلاج الطبي لابنتها. وتوافق على سداد 180,000 SAR.')),
                CaseOption(Bi('Ask Sarah to generally describe her travel and expense process without mentioning specific allegations', 'طلب أن تصف Sarah بشكل عام عملية سفرها ومصروفاتها دون ذكر اتهامات محددة'), feedback: Bi('While open-ended questions are useful at the start, you must eventually present specific evidence. If Sarah provides a false explanation of her process, that becomes additional evidence of deception. Open questions should lead to evidence-based questions.', 'رغم أن الأسئلة المفتوحة مفيدة في البداية، فإنه يتعين عليك في النهاية عرض أدلة محددة. فإذا قدمت Sarah تفسيرا كاذبا لعمليتها، أصبح ذلك دليلا إضافيا على الخداع. وينبغي أن تفضي الأسئلة المفتوحة إلى أسئلة قائمة على الأدلة.')),
                CaseOption(Bi('Let legal counsel handle the entire interview while you observe', 'ترك المستشار القانوني يتولى المقابلة بأكملها بينما تراقب أنت'), feedback: Bi('Legal counsel should be present to protect the organization\'s interests, but Internal Audit should lead the interview. Auditors understand the evidence and financial details better than attorneys. Legal provides guidance on employee rights and admissibility of statements.', 'ينبغي أن يحضر المستشار القانوني لحماية مصالح المؤسسة، لكن على التدقيق الداخلي قيادة المقابلة. فالمدققون يفهمون الأدلة والتفاصيل المالية أفضل من المحامين. ويقدم المستشار القانوني الإرشاد بشأن حقوق الموظف ومدى مقبولية الأقوال.')),
            ]),
